/* 全站链接缓存击穿：点击时给 case/samples 链接自动补 v=3 */
document.addEventListener("click",function(e){
  var a=e.target&&e.target.closest?e.target.closest("a[href]"):null;
  if(!a)return;
  var h=a.getAttribute("href")||"";
  if(h.indexOf("v=")>=0)return;
  if(/\/?case\.html\?/.test(h)){a.setAttribute("href",h+"&v=3")}
  else if(/\/?samples\.html/.test(h)){a.setAttribute("href",h+(h.indexOf("?")<0?"?":"&")+"v=3")}
},true);
